/* class-wise results + positions (examinations) */
function CLSDATA(){
 const per={};
 (S.exams||[]).forEach(e=>{const a=per[e.sid]||(per[e.sid]={m:0,t:0,n:0});a.m+=+e.marks||0;a.t+=+e.total||0;a.n++});
 const by={};
 (TAC()===null?(S.students||[]):(S.students||[]).filter(x=>TSOK(x)&&TFULLS(x))).forEach(t=>{const a=per[t.id];if(!a||!a.t)return;const p=a.m/a.t*100;(by[t.cls]=by[t.cls]||[]).push({id:t.id,name:t.name,cls:t.cls,sec:t.sec,roll:t.roll,m:a.m,t:a.t,p,g:gr(p),n:a.n})});
 Object.values(by).forEach(L=>{L.sort((a,b)=>b.p-a.p||String(a.name).localeCompare(b.name));let pos=0,last=null;L.forEach((r,i)=>{if(last===null||Math.abs(r.p-last)>1e-9){pos=i+1;last=r.p}r.pos=pos})});
 return by}
function CLSPOS(){
 const by=CLSDATA(),keys=Object.keys(by).sort((a,b)=>clsNum(a)-clsNum(b));
 const cur=CF.exams&&CF.exams!='All'&&by[CF.exams]?CF.exams:'All';
 const head=`<div class="cr-h"><span class="cr-i">${ic('exa')}</span><div><h3>Class-wise results</h3><p>Result and position of every student inside their own class</p></div></div>`;
 if(!keys.length)return`<section class="card cr">${head}<p class="em">No marks entered yet.</p></section>`;
 const chips=`<div class="cf cf-in"><div class="cf-r"><button type="button" class="cf-b ${cur=='All'?'on':''}" data-a="cwf" data-k="exams" data-id="All">All classes<i>${keys.length}</i></button>${keys.map(c=>`<button type="button" class="cf-b ${c==cur?'on':''}" data-a="cwf" data-k="exams" data-id="${esc(c)}">${esc(c)}<i>${by[c].length}</i></button>`).join('')}</div></div>`;
 const stats=L=>{const avg=L.reduce((a,r)=>a+r.p,0)/L.length,pass=L.filter(r=>r.p>=50).length;return{avg,pass,pp:Math.round(pass/L.length*100),top:L[0]}};
 let body='';
 if(cur=='All'){
  body=`<div class="cr-g">${keys.map(c=>{const L=by[c],t=stats(L);return`<button type="button" class="cr-c" data-a="cwf" data-k="exams" data-id="${esc(c)}"><div class="cr-ct"><b>${esc(c)}</b><span>${L.length} student${L.length==1?'':'s'}</span></div><div class="cr-cv"><strong>${Math.round(t.avg)}%</strong><small>class average</small></div><div class="cr-bar"><i style="width:${Math.min(100,t.avg)}%"></i></div><div class="cr-cf"><span class="cr-pass">${t.pp}% passed</span><span class="cr-top">${ic('exa')}${esc(t.top.name)}</span></div></button>`}).join('')}</div>`;
 }else{
  const L=by[cur],t=stats(L);
  const mini=`<div class="cr-m"><div><small>Students</small><b>${L.length}</b></div><div><small>Average</small><b>${Math.round(t.avg)}%</b></div><div><small>Passed</small><b>${t.pp}%</b></div><div><small>Highest</small><b>${Math.round(t.top.p)}%</b></div></div>`;
  const rows=L.map(r=>`<div class="cr-r ${r.pos<=3?'r'+r.pos:''}"><span class="cr-p">${r.pos}</span><div class="cr-n"><b>${esc(r.name)}</b><small>${r.roll?'Roll '+esc(r.roll)+' \u00b7 ':''}${esc(r.cls)}${r.sec?' - '+esc(r.sec):''}</small><div class="cr-bar"><i style="width:${Math.min(100,r.p)}%"></i></div></div><div class="cr-v"><b>${Math.round(r.p)}%</b>${badge(r.g)}<small>${r.m}/${r.t}</small></div></div>`).join('');
  body=`${mini}<h4 class="cr-s">${esc(cur)} positions</h4><div class="cr-l">${rows}</div>`;
 }
 return`<section class="card cr">${head}${chips}${body}</section>`}

