function ENT(c,own){const t=c=='demo'&&CLOUD?DEMOT:PLT.tenants.find(x=>x.code==c);if(!t&&!CLOUD)return;if(!own&&t&&!ACC(EFF(t))){location.hash='#blocked';return}if(t&&(!CLOUD||c=='demo'))SEEDT(t,!t.demo);try{sessionStorage.setItem('dyn_t',c);if(own)sessionStorage.setItem('ls_ses',JSON.stringify({role:'admin',name:'ESMOS Owner'}));else sessionStorage.removeItem('ls_ses')}catch(e){}location.hash=own?'#dashboard':'#login';location.reload()}
function BLANK(n){const d=seed();for(const x in d)if(Array.isArray(d[x]))d[x]=[];d.att={};d.al={};d.set.name=n;d.auth={admin:{u:'',p:''}};return d}
function CPLX(p){if(!CREADY){document.querySelector('.app').style.display='none';document.getElementById('lgn').hidden=true;p.hidden=false;p.innerHTML='<div class="ps mu" style="text-align:center">Loading...</div>';return true}
if(CST.status!='active'&&!OWQ()){try{sessionStorage.removeItem('dyn_t');sessionStorage.removeItem('ls_ses')}catch(e){}location.hash='#blocked';location.reload();return true}
p.hidden=true;return false}
function BOOTC(){rpc('school_status',{p_code:DT}).then(async st=>{CST=st||{status:'none'};if(CST.name)S.set.name=CST.name;if(SES().role=='admin'&&TOK&&(CST.status=='active'||OWQ())){try{const d=await rpc('school_load',{p_code:DT});S=d||BLANK(CST.name);CAN=true;ensure()}catch(e){setSES(null)}}else setSES(null);CREADY=true;draw()}).catch(()=>{CST={status:'none'};CREADY=true;draw()})}
const UEQ=(a,b)=>{const t=x=>String(x==null?'':x).trim().toLowerCase();if(t(a)&&t(a)==t(b))return true;const x=PNAME('employee',a);return!!x&&x==PNAME('employee',b)};
function ATTMERGE(mine,base,srv){let n=0;['att','satt','eatt','emeta','attm'].forEach(k=>{const m=(mine&&mine[k])||{},b=(base&&base[k])||{};Object.keys(m).forEach(d=>{const md=m[d]||{},bd=b[d]||{};Object.keys(md).forEach(id=>{if(JSON.stringify(md[id])!==JSON.stringify(bd[id])){srv[k]=srv[k]||{};srv[k][d]=srv[k][d]||{};srv[k][d][id]=md[id];n++}})})});const am=(mine&&mine.al)||{},ab=(base&&base.al)||{};Object.keys(am).forEach(x=>{if(!(x in ab)){srv.al=srv.al||{};if(!(x in srv.al)){srv.al[x]=am[x];n++}}});return n}
async function CLOGIN(r,u,p,up){const er=document.getElementById('er');er.textContent='Please wait...';try{let k;
if(r=='admin'){if(up)await efn({action:'admin_signup',code:DT,email:u,password:p},1);await sbAuth('in',u,p);const st=await rpc('school_claim',{p_code:DT});const d=await rpc('school_load',{p_code:DT});S=d||BLANK(st.name);CAN=true;k={role:'admin',name:'Administrator'}}
else{try{await sbAuth('in',PMAIL(DT,r,u),p)}catch(e){throw new Error('Wrong username or password. Please try again.')}const d=await rpc('school_load',{p_code:DT});if(!d)throw new Error('This school has no data yet. Please ask your school admin.');S=d;CAN=(r=='employee');ensure();const L=x=>String(x||'').toLowerCase();
if(r=='employee'){const s=(S.staff||[]).find(x=>UEQ(x.user,u));if(!s)throw new Error('Your login worked, but this username is not in the staff list. Please ask your school admin to check your username.');k={role:'employee',id:s.id,name:s.name}}
else if(r=='parent'){const s=(S.students||[]).find(x=>intl(x.phone)==intl(u))||(S.students||[])[0];if(!s)throw new Error('No student found for this login. Please ask your school admin.');k={role:'parent',g:s.guardian,name:s.guardian}}
else{const s=(S.students||[]).find(x=>UEQ(x.adm,u))||(S.students||[])[0];if(!s)throw new Error('No student found for this login. Please ask your school admin.');k={role:'student',id:s.id,name:s.name}}}
ensure();setSES(k);S.logins=S.logins||[];S.logins.unshift({r:PORT[r][0]+': '+k.name,t:new Date().toLocaleString()});S.logins=S.logins.slice(0,10);save();$('#v').classList.add('fx');location.hash='#'+nav(k)[0][0];draw();setTimeout(()=>$('#v').classList.remove('fx'),1900)}catch(e){er.textContent=e.message}}
