function anSave(){const t=$('#ant').value.trim(),x=$('#anm').value.trim();if(!t){toast('Write a title');return}if(!x){toast('Write the message');return}const a={id:uid(),title:t,text:x,aud:$('#ana').value,cls:$('#anc').value,pri:$('#anp').value,on:anNow(),by:'Admin'};S.ann=S.ann||[];S.ann.push(a);let n=0;if($('#anw').checked&&(a.aud=='all'||a.aud=='parents')){const seen={};S.students.filter(s=>s.status=='Active'&&(a.cls=='All'||s.cls==a.cls)).forEach(s=>{const k=intl(s.phone);if(seen[k])return;seen[k]=1;sendMsg(s.id,'Announcement','Dear '+s.guardian+', '+t+': '+x);n++})}lg('Announcement sent: '+t);try{save()}catch(e){}$('#md').hidden=true;toast('Announcement sent'+(n?' and '+n+' WhatsApp messages queued':''));draw()}
