function cmModal(){const kids=PKIDS();if(!kids.length){toast('No student found');return}const m=$('#md');m.hidden=false;m.innerHTML=`<form class="mb" id="cmf"><h3>New complaint</h3><label>Child<select id="cmk">${kids.map(s=>`<option value="${s.id}">${esc(s.name)} (${esc(s.cls)})</option>`).join('')}</select></label><label>Send to<select id="cmto"><option value="admin">Admin</option><option value="teacher">A teacher</option><option value="both">Admin and a teacher</option></select></label><label id="cmtw" style="display:none">Teacher<select id="cmt"></select></label><label>Subject<input id="cms" autocomplete="off" placeholder="e.g. Homework is too much"></label><label>Details<textarea id="cmd" rows="4" placeholder="Explain the problem"></textarea></label><div class="ra"><button type="button" class="bt gh" data-a="close">Cancel</button><button type="button" class="bt" data-cm="save">Send</button></div></form>`;cmFill();$('#cmf').onsubmit=e=>{e.preventDefault();cmSave()}}
