document.addEventListener('click',e=>{const b=e.target.closest('[data-an],[data-cm]');if(!b)return;const a=b.dataset.an,c=b.dataset.cm;if(a=='add')anModal();else if(a=='save')anSave();else if(a=='del'){if(!b.dataset.armed){b.dataset.armed=1;b.textContent='Tap again to delete';return}S.ann=(S.ann||[]).filter(x=>x.id!=b.dataset.id);try{save()}catch(x){}toast('Deleted');draw()}else if(c=='add')cmModal();else if(c=='save')cmSave();else if(c=='reply')cmReply(b.dataset.id);else if(c=='done'){const k=(S.cmp||[]).find(x=>x.id==b.dataset.id);if(!k)return;CPOST('status',{id:k.id,st:'Resolved'}).then(()=>{k.st='Resolved';try{save()}catch(x){}toast('Marked resolved');draw()}).catch(x=>toast('Could not update: '+x.message))}else if(c=='del'){if(!b.dataset.armed){b.dataset.armed=1;b.textContent='Tap again to delete';return}S.cmp=(S.cmp||[]).filter(x=>x.id!=b.dataset.id);try{save()}catch(x){}toast('Deleted');draw()}});
