payall(){let n=0;S.staff.filter(s=>s.status=='Active'&&!S.payroll.some(p=>p.sid==s.id&&p.month==(window.PMO||mm()))).forEach(s=>{S.payroll.push({sid:s.id,month:(window.PMO||mm()),net:PN(s),date:today()});n++});save();toast(n+' salaries paid');draw()},
slip(k,id){const s=S.staff.find(x=>x.id==id),r=(a,b)=>`<div class="cb"><span>${a}</span><b style="margin-left:auto">${b}</b></div>`;form('Salary slip - '+(window.PMO||mm()),[],{},()=>{},'Close',r('Employee',esc(s.name))+r('Basic salary',money(s.salary))+r('Allowances',money(s.allow))+r('Deductions and advance',money(s.ded))+r('Net pay',money(PN(s))))},
