eset(){form('School settings',[['name','School name'],['session','Academic session'],['dueDay','Fee due day (1-28)','number'],['fine','Late fine (Rs)','number'],['api','WhatsApp API key','password']],S.set,v=>{Object.assign(S.set,v);lg('Settings changed');toast('Settings saved')})},
bkup(){if(!LOC){CBKUP();return}$('#bk').value=JSON.stringify(S);toast('Backup created. Copy the text and keep it safe')},
