const CH={rvhm(v){RV.m=v;draw()},rvh(v,t){RV[t.dataset.k]=v;draw()},rule(v,t){S.rules[t.dataset.r]=t.checked;save()},tfa(v,t){S.set.tfa=t.checked?1:0;save()},ad(v){A.d=v||today();draw()},ac(v){A.c=v;draw()},pg(v){P.g=v;draw()},wt(v){W.aud=$('#wa-aud').value;W.no=$('#wa-no').value;W.tpl=v;W.text=TPL[v][1];draw()},tperm(v,t){const x=S.staff.find(z=>z.id==t.dataset.id);if(!x)return;if(!Array.isArray(x.perms))x.perms=TPM.map(m=>m[0]).filter(m=>TPDEF(x,m));const m=t.dataset.m,i=x.perms.indexOf(m);if(t.checked&&i<0)x.perms.push(m);if(!t.checked&&i>=0)x.perms.splice(i,1);lg('Teacher permission changed: '+x.name);save();draw()},
perm(v,t){const a=S.roles[t.dataset.r],m=t.dataset.m,i=a.indexOf(m);if(t.checked&&i<0)a.push(m);if(!t.checked&&i>=0)a.splice(i,1);lg('Permission changed: '+t.dataset.r);save()}};
/* ===== Teacher: enter marks by roll no (roll nos are given by admin) ===== */
H.rmodal=function(){const c=rsCfg(),cls=TCLX([...new Set(CL.concat(S.students.map(s=>s.cls)))]),subs=[...new Set(S.exams.map(e=>e.subject))],m=$('#md');m.hidden=false;
m.innerHTML=`<form class="mb" id="rmf"><h3>Enter marks by roll no</h3><p class="mu">Roll numbers are given by the admin. Choose the class, type the roll no and the marks. Marks go only to that child's Student and Parent portal.</p><label>Class<select name="cls">${cls.map(x=>`<option${c.cls==x?' selected':''}>${esc(x)}</option>`).join('')}</select></label><label>Roll no<input name="roll" autocomplete="off" inputmode="numeric" required placeholder="e.g. 7"></label><div id="rmw" class="mu" style="margin:-4px 0 12px;min-height:20px"></div><label>Subject<input name="subject" list="rsub2" required value="${esc(c.subject)}" placeholder="e.g. Mathematics"><datalist id="rsub2">${subs.map(x=>`<option value="${esc(x)}">`).join('')}</datalist></label><label>Test<select name="test">${['Monthly test','Midterm','Final'].map(x=>`<option${c.test==x?' selected':''}>${x}</option>`).join('')}</select></label><label>Marks obtained<input name="marks" type="number" min="0" step="0.5" required></label><label>Total marks<input name="total" type="number" min="1" step="any" required value="${c.total}"></label><div class="ra"><button type="button" class="bt gh" data-a="close">Cancel</button><button type="button" class="bt gh" id="rmn">Save &amp; next</button><button class="bt">Save</button></div></form>`;
const f=m.querySelector('form'),E=f.elements,W=m.querySelector('#rmw');
const find=()=>{const r=E.roll.value.trim().toLowerCase();return r?S.students.find(s=>s.cls==E.cls.value&&s.status=='Active'&&String(s.roll||'').trim().toLowerCase()==r):null};
const look=()=>{const s=find(),r=E.roll.value.trim();if(!r){W.innerHTML='';return}if(!s){W.innerHTML='<span style="color:#dc2626">No active student with roll no '+esc(r)+' in '+esc(E.cls.value)+'</span>';return}const ex=S.exams.find(e=>rsKey(e)==rsKey({sid:s.id,subject:E.subject.value,test:E.test.value}));W.innerHTML='<b>'+esc(s.name)+'</b> &middot; Adm '+esc(s.adm)+(ex?' &middot; current marks '+ex.marks+'/'+ex.total+' (will be updated)':'')};
const go=next=>{if(!f.reportValidity())return;const s=find();if(!s){toast('Roll no not found in this class');return}if(!TSUBOK(s,E.subject.value)){toast('In '+s.cls+' you can enter marks only for: '+(TSUBSFOR(s.cls).join(', ')||'no subject set'));return}const sub=E.subject.value.trim(),tot=+E.total.value,mk=+E.marks.value,test=E.test.value;if(!(tot>0)||isNaN(mk)||mk<0||mk>tot){toast('Marks must be between 0 and '+tot);return}
const key=rsKey({sid:s.id,subject:sub,test}),ex=S.exams.find(e=>rsKey(e)==key),by=(S.staff.find(x=>x.id==SES().id)||{}).name||'Admin',on=new Date().toLocaleDateString(),chg=!ex||ex.marks!=mk;
if(ex){ex.marks=mk;ex.total=tot;ex.by=by;ex.on=on}else S.exams.push({id:Math.max(0,...S.exams.map(e=>e.id))+1,sid:s.id,subject:sub,test,marks:mk,total:tot,by,on});
if(chg)sendMsg(s.id,'Result notification','Dear '+s.guardian+', '+s.name+(s.roll?' (Roll no '+s.roll+')':'')+' scored '+mk+'/'+tot+' in '+sub+' ('+test+'). Full result is in the Parent Portal.');
Object.assign(rsCfg(),{cls:E.cls.value,subject:sub,test,total:tot});lg('Marks saved: '+s.name+' '+sub);try{save()}catch(e){}toast(s.name+' (Roll '+s.roll+'): '+mk+'/'+tot+' saved');
if(next){E.roll.value='';E.marks.value='';W.innerHTML='';E.roll.focus();draw()}else{m.hidden=true;draw()}};
f.onsubmit=e=>{e.preventDefault();go(false)};m.querySelector('#rmn').onclick=()=>go(true);
['input','change'].forEach(ev=>f.addEventListener(ev,look));
E.roll.addEventListener('keydown',e=>{if(e.key=='Enter'){e.preventDefault();E.marks.focus()}});
E.marks.addEventListener('keydown',e=>{if(e.key=='Enter'){e.preventDefault();go(true)}});
setTimeout(()=>E.roll.focus(),50)};
{const _a=H.add;H.add=function(k){if(k=='exams')return H.rmodal();return _a.apply(this,arguments)}}

