const ACN=[['adash','home','Accounts Dashboard','Collections, dues and expenses at a glance'],['acollect','fee','Collect Fee','Find a student by roll no, admission no or name'],['apays','fin','Payments & Daily Report','Every payment received, by date and mode'],['adef','par','Defaulters','Overdue fees and parent reminders']];
