function adash(){const F=fin(),td=today(),P=FCLS()?S.pays.filter(p=>payCls(p)==FCLS()):S.pays,tp=P.filter(p=>p.date==td),col=sum(tp,p=>p.amt),pm=P.filter(p=>p.date.slice(0,7)==mm()),u=S.staff.find(x=>x.id==SES().id)||{name:'Accountant'},
dl=act().filter(s=>!FCLS()||s.cls==FCLS()).map(s=>({s,b:sum(S.fees.filter(f=>f.sid==s.id&&fst(f)=='Overdue'),bal)})).filter(x=>x.b>0).sort((a,b)=>b.b-a.b).slice(0,6),
cp=CL.filter(c=>!FCLS()||c==FCLS()).map(c=>[c,sum(S.students.filter(s=>s.cls==c),s=>owed(s.id))]),mx=Math.max(1,...cp.map(x=>x[1]));
return`<div class="hero"><div><h2>Welcome, ${esc(u.name)}</h2><p>Accounts - ${esc(S.set.name)}. Collections, dues and expenses in one place.</p></div><div><a class="bt" href="#acollect">Collect fee</a><a class="bt" href="#adef">Defaulters</a><a class="bt" href="#finance">Add expense</a><a class="bt" href="#payroll">Payroll</a></div></div>
${FCHIPS('fin',FNOTE())}<div class="g4">${stat('fee','Collected today',money(col),tp.length+' payments today','c-g')}${stat('fin','Collected this month',money(F.revM),'Net '+money(F.revM-F.eM),'c-b')}${stat('adm','Pending fees',money(F.pend),S.fees.filter(f=>bal(f)>0).length+' open challans','c-r')}${stat('pay','Expenses this month',money(F.eM),'Bills, rent and salaries','c-r')}</div>
<div class="two"><div class="card"><div class="tb"><h3>Recent payments</h3><a class="bt sm gh" href="#apays" style="margin-left:auto">All payments</a></div>${P.slice(-8).reverse().map(payLine).join('')||'<p class="em">No payments yet.</p>'}</div><div class="card"><div class="tb"><h3>Overdue - highest balance</h3><a class="bt sm gh" href="#adef" style="margin-left:auto">See all</a></div>${dl.map(x=>`<div class="cb"><span>${esc(x.s.name)} <span class="mu">${esc(x.s.cls)}</span></span><b style="margin-left:auto">${money(x.b)}</b><button class="bt sm" data-a="rem" data-id="${x.s.id}">Remind</button></div>`).join('')||'<p class="em">No overdue fees.</p>'}</div></div>
<div class="two"><div class="card"><h3>Collection by payment mode (this month)</h3>${modeBars(pm)}</div><div class="card"><h3>Pending fees by class</h3>${cp.map(x=>`<div class="mu" style="margin:0">${esc(x[0])}: <b>${money(x[1])}</b></div><div class="pb"><div style="width:${x[1]/mx*100}%"></div></div>`).join('')}</div></div>`}
function acRes(){const q=ACS.q.trim().toLowerCase(),c=ACS.c;if(!q&&!c)return'<p class="em">Type a roll no, admission no, name or phone - or pick a class.</p>';
let L=S.students.filter(s=>s.status=='Active'&&(!c||s.cls==c)&&(!q||[s.roll,s.adm,s.name,s.guardian,s.phone].join(' ').toLowerCase().indexOf(q)>-1)).sort((a,b)=>(parseInt(a.roll)||9999)-(parseInt(b.roll)||9999)||String(a.name).localeCompare(b.name));const tot=L.length;L=L.slice(0,25);if(!L.length)return'<p class="em">No student found.</p>';
return L.map(s=>{const fs=S.fees.filter(f=>f.sid==s.id).slice().reverse();return`<div class="card" style="margin-bottom:12px"><div class="tb"><h3>${esc(s.name)} <span class="mu">Roll ${esc(s.roll||'-')} &middot; ${esc(s.cls)} &middot; ${esc(s.adm)}</span></h3><button class="bt sm blue" data-a="acnew" data-id="${s.id}" style="margin-left:auto">New challan</button></div><div class="mu">Guardian: ${esc(s.guardian)} &middot; ${esc(s.phone)} &middot; Total due: <b>${money(owed(s.id))}</b></div>${fs.map(f=>`<div class="cb"><span>${esc(f.month)}</span><span class="mu" style="margin:0 0 0 auto">Due ${esc(f.due)} &middot; Paid ${money(f.paid)} of ${money(f.amount)}</span>${badge(fst(f))}${bal(f)>0?`<button class="bt sm" data-a="col" data-k="fees" data-id="${f.id}">Collect</button>`:''}${f.paid>0?`<button class="bt sm gh" data-a="rec" data-k="fees" data-id="${f.id}">Receipt</button>`:''}</div>`).join('')||'<p class="em">No challans yet.</p>'}</div>`}).join('')+(tot>25?`<p class="mu">Showing 25 of ${tot}. Type more to narrow down.</p>`:'')}
function acollect(){return`<div class="card" style="margin-bottom:14px"><h3>Find student</h3><div style="display:flex;gap:8px;flex-wrap:wrap"><select data-acc="1"><option value="">All classes</option>${CL.map(c=>`<option${ACS.c==c?' selected':''}>${c}</option>`).join('')}</select><input id="acq" data-acq="1" placeholder="Roll no / adm no / name / phone" value="${esc(ACS.q)}" style="min-width:250px"></div></div><div id="acr">${acRes()}</div>`}
function apRange(){const f=APS.from||today().slice(0,8)+'01',t=APS.to||today();return{f,t,L:S.pays.filter(p=>p.date>=f&&p.date<=t&&(!APS.mode||p.mode==APS.mode)&&(!APS.c||payCls(p)==APS.c)).slice().sort((a,b)=>b.date.localeCompare(a.date))}}
function apRows(L){return L.map(p=>{const s=pst(p),f=pfe(p);return[p.date,p.rn||'-',s?s.name:'Unknown',s?(s.roll||''):'',s?s.cls:'',f?f.month:'',p.mode,p.by||'',p.amt]})}
