apcsv(){const r=apRange(),q=v=>'"'+String(v==null?'':v).replace(/"/g,'""')+'"',csv=['Date,Receipt,Student,Roll,Class,Fee,Mode,Received by,Amount'].concat(apRows(r.L).map(x=>x.map(q).join(','))).join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='payments-'+r.f+'-to-'+r.t+'.csv';document.body.appendChild(a);a.click();a.remove()},
