function rcCfg(){FL.rc=FL.rc||{cls:'',test:'Monthly test'};if(!FL.rc.cls){const u=SES(),t=u.role=='employee'?S.staff.find(x=>x.id==u.id):null;FL.rc.cls=(t?rcStaffLbl(t):'')||(S.students[0]?rcLbl(S.students[0]):CL[0])}return FL.rc}
