function rcBuild(s,test){const rows=[];rcSubs().forEach(sb=>{const e=rcFind(s.id,sb,test);if(e)rows.push(e)});const g=rows.reduce((a,e)=>a+e.marks,0),t=rows.reduce((a,e)=>a+e.total,0),pc=t?Math.round(g/t*100):0;return{rows,g,t,pc,gd:gr(pc)}}
function rcCard(s,test){const r=rcBuild(s,test),a=attOf(s),rem=(S.rcrem||{})[s.id+'|'+test]||'';
return`<div class="card" style="margin-bottom:12px"><h3>${esc(s.name)} - Report Card (${esc(test)})</h3><p class="mu">${esc(s.cls)} &middot; Roll no ${esc(s.roll||'-')} &middot; Adm no ${esc(s.adm)}</p>${r.rows.length?`<div class="tw cv"><table><thead><tr><th>Subject</th><th>Marks</th><th>%</th><th>Grade</th><th>Teacher</th></tr></thead><tbody>${r.rows.map(e=>`<tr><td class="ttl">${esc(e.subject)}</td><td data-l="Marks">${e.marks} / ${e.total}</td><td data-l="%">${Math.round(e.marks/e.total*100)}%</td><td data-l="Grade">${badge(gr(e.marks/e.total*100))}</td><td data-l="Teacher">${esc(e.by||'')}</td></tr>`).join('')}<tr><td><b>Total</b></td><td><b>${r.g} / ${r.t}</b></td><td><b>${r.pc}%</b></td><td>${badge(r.gd)}</td><td></td></tr></tbody></table></div>`:'<p class="em">No marks entered yet.</p>'}<p class="mu" style="margin-top:10px">Attendance: <b>${a.pc}%</b> over ${a.t} days</p>${rem?`<p><b>Remarks:</b> ${esc(rem)}</p>`:''}</div>`}
function rcPage(){const c=rcCfg(),cls=rcLabels(),subs=rcSubs(),mine=rcMine(c.cls),st=rcAp(c.cls,c.test),lock=(st.st=='Pending'||st.st=='Approved')&&!rcIsAdm(),ok=sb=>!lock&&(!mine||mine.indexOf(sb.toLowerCase())>-1||rcOwn(sb)),
kids=S.students.filter(s=>rcLbl(s)==c.cls&&s.status=='Active').sort((a,b)=>String(a.sec||'').localeCompare(String(b.sec||''))||(parseInt(a.roll)||9999)-(parseInt(b.roll)||9999)||String(a.name).localeCompare(b.name)),
tt=sb=>{const e=S.exams.find(x=>String(x.subject||'').trim().toLowerCase()==sb.toLowerCase()&&x.test==c.test&&kids.some(k=>k.id==x.sid));return e?e.total:100};
return`${rcPendList()}<div class="card" style="margin-bottom:14px"><h3>Report cards</h3><p class="mu">Every teacher fills only their own subject column for each child. Marks go straight into that child's report card in the Student and Parent portal. ${mine?'You can edit: <b>'+esc(mine.join(', ')||'no subject assigned')+'</b>.':rcIsAdm()?'Admin can edit every subject.':'You are the class teacher of this section: fill every subject to make the complete report card, then send it to admin.'}</p>
<div style="display:flex;gap:8px;flex-wrap:wrap"><button class="bt gh" data-rc="subadd">+ Add subject</button><select data-rcf="cls">${cls.map(x=>`<option${c.cls==x?' selected':''}>${esc(x)}</option>`).join('')}</select><select data-rcf="test">${['Monthly test','Midterm','Final'].map(x=>`<option${c.test==x?' selected':''}>${x}</option>`).join('')}</select></div></div>
${rcApBar(c,st)}<div class="card"><div class="tw cv rcpg"><table><thead><tr><th>Roll</th><th>Student</th>${subs.map(sb=>`<th>${esc(sb)}${ok(sb)?` <button class="bt gh" data-rc="subedit" data-sub="${esc(sb)}" title="Edit subject" style="padding:2px 7px">&#9998;</button>`:''}<br><span class="mu" style="margin:0">out of <input class="rct" data-sub="${esc(sb)}" type="number" min="1" value="${tt(sb)}" style="width:60px"${ok(sb)?'':' disabled'}></span></th>`).join('')}<th>Total</th><th>%</th><th>Grade</th><th></th></tr></thead><tbody>${kids.map(s=>{const r=rcBuild(s,c.test);return`<tr><td><b>${esc(s.roll||'')}</b>${s.sec?' <span class="mu">('+esc(s.sec)+')</span>':''}</td><td class="ttl">${esc(s.name)}</td>${subs.map(sb=>{const e=rcFind(s.id,sb,c.test);return`<td data-l="${esc(sb)}"><input class="rcm" type="number" min="0" step="0.5" data-sid="${s.id}" data-sub="${esc(sb)}" value="${e?e.marks:''}" style="width:70px"${ok(sb)?'':' disabled'}></td>`}).join('')}<td>${r.rows.length?r.g+'/'+r.t:'-'}</td><td>${r.rows.length?r.pc+'%':'-'}</td><td>${r.rows.length?badge(r.gd):''}</td><td><button class="bt gh" data-rc="view" data-sid="${s.id}">Report card</button></td></tr>`}).join('')||`<tr><td colspan="${subs.length+5}" class="em">No active students in this class.</td></tr>`}</tbody></table></div><div style="margin-top:12px"><button class="bt" data-rc="save">Save ${mine?'my subject':'all'} marks</button></div></div>`}
function rcSave(){const c=rcCfg(),by=(S.staff.find(x=>x.id==SES().id&&SES().role=='employee')||{}).name||'Admin',on=new Date().toLocaleDateString(),tot={};document.querySelectorAll('.rct:not(:disabled)').forEach(i=>tot[i.dataset.sub]=+i.value);const chg={};let n=0;
for(const i of document.querySelectorAll('.rcm:not(:disabled)')){const v=i.value.trim();if(v==='')continue;const m=+v,t=tot[i.dataset.sub];if(!(t>0)){toast('Set total marks for '+i.dataset.sub);return}if(isNaN(m)||m<0||m>t){const st=S.students.find(x=>x.id==i.dataset.sid);toast('Marks of '+(st?st.name:'student')+' in '+i.dataset.sub+' must be between 0 and '+t);return}}
document.querySelectorAll('.rcm:not(:disabled)').forEach(i=>{const v=i.value.trim();if(v==='')return;const m=+v,t=tot[i.dataset.sub],sid=+i.dataset.sid,ex=rcFind(sid,i.dataset.sub,c.test);if(!ex||ex.marks!=m||ex.total!=t)(chg[sid]=chg[sid]||[]).push(i.dataset.sub+' '+m+'/'+t);if(ex){ex.marks=m;ex.total=t;ex.by=by;ex.on=on}else S.exams.push({id:Math.max(0,...S.exams.map(e=>e.id))+1,sid,subject:i.dataset.sub,test:c.test,marks:m,total:t,by,on});n++});

lg('Report card marks saved: '+c.cls+' '+c.test+' ('+n+')');try{save()}catch(e){}toast(n+' marks saved to report cards.');draw()}
function rcView(sid){const s=S.students.find(x=>x.id==sid),c=rcCfg(),m=$('#md');if(!s)return;m.hidden=false;m.innerHTML=`<div class="mb">${rcCard(s,c.test)}<label>Teacher remarks<textarea id="rcrem" rows="2" style="width:100%">${esc((S.rcrem||{})[s.id+'|'+c.test]||'')}</textarea></label><div class="ra"><button type="button" class="bt gh" data-a="close">Close</button><button type="button" class="bt gh" data-rc="print" data-sid="${s.id}">Print</button><button type="button" class="bt" data-rc="rem" data-sid="${s.id}">Save remarks</button></div></div>`}
function rcPrint(sid){const s=S.students.find(x=>x.id==sid),c=rcCfg();if(!s)return;const w=window.open('','_blank');if(!w){toast('Allow pop-ups to print');return}w.document.write('<title>Report card</title><style>body{font:14px Arial;margin:20px}table{border-collapse:collapse;width:100%}td,th{border:1px solid #666;padding:6px;text-align:left}</style><h2>'+esc(S.set.name)+'</h2>'+rcCard(s,c.test)+'<script>setTimeout(function(){print()},300)<\/script>');w.document.close()}
function rcPortal(s){const t=['Monthly test','Midterm','Final'].filter(x=>rcAp(rcLbl(s),x).st=='Approved'&&rcBuild(s,x).rows.length);return t.length?t.map(x=>rcCard(s,x)).join(''):`<div class="card" style="margin-bottom:12px"><h3>${esc(s.name)}: Report Card</h3><p class="em">No report card yet. It appears here after the school approves it.</p></div>`}
document.addEventListener('change',e=>{const x=e.target;if(x&&x.dataset&&x.dataset.rcf){rcCfg()[x.dataset.rcf]=x.value;draw()}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-rc]');if(!b)return;const a=b.dataset.rc;if(a=='save')rcSave();else if(a=='view')rcView(+b.dataset.sid);else if(a=='print')rcPrint(+b.dataset.sid);else if(a=='rem'){S.rcrem=S.rcrem||{};S.rcrem[b.dataset.sid+'|'+rcCfg().test]=$('#rcrem').value.trim();try{save()}catch(x){}toast('Remarks saved');rcView(+b.dataset.sid);draw()}});

/* ===== Report card: add / edit / delete subjects (write any subject name) ===== */
function rcOwn(sb){const u=SES();if(u.role!='employee')return false;return(S.subjects||[]).some(o=>String(o.name).trim().toLowerCase()==String(sb).toLowerCase()&&o.by==u.id)}
function rcSubModal(old){const m=$('#md');m.hidden=false;m.innerHTML=`<form class="mb" id="rcsf"><h3>${old?'Edit subject':'Add subject'}</h3><p class="mu">Write the subject name in your own words (for example Islamiat, Computer, Drawing).</p><label>Subject name<input id="rcsn" value="${esc(old||'')}" autocomplete="off" placeholder="e.g. Islamiat"></label><div class="ra"><button type="button" class="bt gh" data-a="close">Cancel</button>${old?`<button type="button" class="bt gh" data-rc="subdel" data-old="${esc(old)}">Delete</button>`:''}<button type="button" class="bt" data-rc="subsave" data-old="${esc(old||'')}">Save</button></div></form>`;const i=$('#rcsn');if(i)i.focus();$('#rcsf').onsubmit=e=>{e.preventDefault();rcSubSave(old||'')}}
function rcSubSave(old){const n=($('#rcsn').value||'').trim();if(!n){toast('Write the subject name');return}const k=n.toLowerCase(),ok0=old.toLowerCase();if(k!=ok0&&rcSubs().some(x=>x.toLowerCase()==k)){toast(n+' already exists');return}S.subjects=S.subjects||[];
if(!old){const u=SES();S.subjects.push({name:n,by:u.role=='employee'?u.id:'admin'})}
else{S.subjects.forEach(o=>{if(String(o.name).trim().toLowerCase()==ok0)o.name=n});S.exams.forEach(e=>{if(String(e.subject||'').trim().toLowerCase()==ok0)e.subject=n});S.staff.forEach(t=>{if(t.role=='Teacher'&&t.subject)t.subject=String(t.subject).split(/([,&])/).map(v=>v.trim().toLowerCase()==ok0?n:v).join('')});}
lg('Subject '+(old?'renamed to ':'added: ')+n);try{save()}catch(e){}$('#md').hidden=true;toast('Subject saved: '+n);draw()}
function rcSubDel(old){const k=old.toLowerCase();S.subjects=(S.subjects||[]).filter(o=>String(o.name).trim().toLowerCase()!=k);S.exams=S.exams.filter(e=>String(e.subject||'').trim().toLowerCase()!=k);const st=S.staff.some(t=>t.role=='Teacher'&&String(t.subject||'').split(/[,&]/).some(v=>v.trim().toLowerCase()==k));lg('Subject deleted: '+old);try{save()}catch(e){}$('#md').hidden=true;toast(st?old+' is still in a teacher\'s Staff subject, remove it there too.':'Subject deleted: '+old);draw()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-rc]');if(!b)return;const a=b.dataset.rc;if(a=='subadd')rcSubModal('');else if(a=='subedit')rcSubModal(b.dataset.sub);else if(a=='subsave')rcSubSave(b.dataset.old||'');else if(a=='subdel'){if(!b.dataset.armed){b.dataset.armed=1;b.textContent='Tap again - marks of this subject will be deleted';return}rcSubDel(b.dataset.old)}});

/* ===== Homework & Assignments: teacher gives to selected students by name, shown in Parent/Student portal ===== */
function hwToday(){const n=new Date();return n.getFullYear()+'-'+String(n.getMonth()+1).padStart(2,'0')+'-'+String(n.getDate()).padStart(2,'0')}
function hwMe(){const u=SES();return u.role=='employee'?{id:u.id,name:(S.staff.find(x=>x.id==u.id)||{}).name||'Teacher'}:{id:'admin',name:'Admin'}}
function hwCan(h){const u=SES();if(u.role=='admin')return true;if(u.role=='employee'){const t=S.staff.find(x=>x.id==u.id)||{};return t.role=='Principal'||h.byId==u.id}return false}
function hwNames(h){const L=S.students.filter(s=>h.sids.includes(s.id)),cl=S.students.filter(s=>s.cls==h.cls&&s.status=='Active');return L.length&&L.length==cl.length&&cl.every(s=>h.sids.includes(s.id))?'Whole '+h.cls+' ('+L.length+')':L.map(s=>s.name).join(', ')}
function hwDue(h){return h.due?new Date(h.due+'T00:00:00').toLocaleDateString('en',{day:'numeric',month:'short',year:'numeric'}):''}
function hwItem(h,staff){return`<div class="card" style="margin-bottom:12px"><div class="cb"><b>${esc(h.title)}</b>&nbsp;${badge(h.type)}${h.due&&h.due<hwToday()?badge('Overdue'):''}<span class="mu" style="margin:0 0 0 auto">${esc(h.subject||'')}</span></div>${h.desc?`<p style="white-space:pre-wrap">${esc(h.desc)}</p>`:''}<p class="mu">${staff?esc(h.cls)+' &middot; To: '+esc(hwNames(h))+' &middot; ':''}${h.due?'Due '+hwDue(h)+' &middot; ':''}By ${esc(h.by)}</p>${staff&&hwCan(h)?`<div style="display:flex;gap:8px"><button class="bt gh sm" data-hw="edit" data-id="${h.id}">Edit</button><button class="bt gh sm" data-hw="del" data-id="${h.id}">Delete</button></div>`:''}</div>`}
function hwPage(){S.hw=S.hw||[];const u=SES(),f=FL.hwc||'All',cls=TCLX([...new Set(CL.concat(S.students.map(s=>s.cls)))]);let L=S.hw.slice().sort((a,b)=>b.id-a.id);
if(u.role=='employee'){const t=S.staff.find(x=>x.id==u.id)||{};if(t.role!='Principal')L=L.filter(h=>h.byId==u.id)}if(f!='All')L=L.filter(h=>h.cls==f);
return FCHIPS('hwc')+`<div class="card" style="margin-bottom:14px"><h3>Homework &amp; Assignments</h3><p class="mu">Give homework or an assignment to selected students by name, or to the whole class. It shows in their Parent and Student portal and a WhatsApp message is queued for the parent.</p><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="bt" data-hw="add">+ Give homework / assignment</button></div></div>`+(L.map(h=>hwItem(h,1)).join('')||'<div class="card em">Nothing given yet.</div>')}
function hwPortal(s){S.hw=S.hw||[];const V=window.HWV=window.HWV||{year:'all',mon:'all'},A=S.hw.filter(h=>h.sids.includes(s.id)),dk=h=>String(h.due||h.date||''),yrs=[...new Set(A.map(h=>dk(h).slice(0,4)).filter(y=>/^\d{4}$/.test(y)))].sort().reverse();if(V.year!='all'&&!yrs.includes(V.year))V.year='all';const L=A.filter(h=>(V.year=='all'||dk(h).slice(0,4)==V.year)&&(V.mon=='all'||+dk(h).slice(5,7)-1==+V.mon)).sort((a,b)=>(b.due||'').localeCompare(a.due||'')||b.id-a.id);return`<div class="card" style="margin-bottom:12px"><h3>${esc(s.name)}: Homework &amp; Assignments</h3><div class="fv-f"><label>Month<select data-hv="mon"><option value="all">All months</option>${MN.map((m,i)=>`<option value="${i}"${V.mon!='all'&&V.mon==i?' selected':''}>${m}</option>`).join('')}</select></label><label>Year<select data-hv="year"><option value="all">All years</option>${yrs.map(y=>`<option value="${y}"${V.year==y?' selected':''}>${y}</option>`).join('')}</select></label><div class="fv-n"><span>${L.length} item${L.length==1?'':'s'}</span></div></div>${L.length?'':'<p class="em">No homework found.</p>'}</div>`+L.map(h=>hwItem(h,0)).join('')}
document.addEventListener('change',e=>{const x=e.target;if(!x.dataset||!x.dataset.hv)return;(window.HWV=window.HWV||{year:'all',mon:'all'})[x.dataset.hv]=x.value;try{draw()}catch(y){}});
function hwFill(sel){const c=$('#hwc').value,L=TSTU(S.students).filter(s=>s.cls==c&&s.status=='Active').sort((a,b)=>(parseInt(a.roll)||9999)-(parseInt(b.roll)||9999)||String(a.name).localeCompare(b.name));$('#hwl').innerHTML=L.length?`<label style="display:flex;gap:8px;align-items:center;padding:4px 0"><input type="checkbox" id="hwall" style="width:auto;margin:0"> <b>Select all (${L.length})</b></label>`+L.map(s=>`<label style="display:flex;gap:8px;align-items:center;padding:4px 0"><input type="checkbox" class="hwk" value="${s.id}" style="width:auto;margin:0"${sel.includes(s.id)?' checked':''}> ${esc(s.roll||'')} - ${esc(s.name)}</label>`).join(''):'<p class="em">No active students in this class.</p>'}
function hwModal(id){S.hw=S.hw||[];const h=id?S.hw.find(x=>x.id==id):null,u=SES(),cls=TCLX([...new Set(CL.concat(S.students.map(s=>s.cls)))]),me=u.role=='employee'?String((S.staff.find(x=>x.id==u.id)||{}).subject||'').split(/[,&]/)[0].trim():'',m=$('#md');if(id&&!h)return;m.hidden=false;
const c=h?h.cls:(FL.hwc&&FL.hwc!='All'?FL.hwc:cls[0]);
m.innerHTML=`<form class="mb" id="hwf" data-id="${h?h.id:''}"><h3>${h?'Edit':'Give'} homework / assignment</h3><label>Type<select id="hwt">${['Homework','Assignment'].map(x=>`<option${h&&h.type==x?' selected':''}>${x}</option>`).join('')}</select></label><label>Class<select id="hwc">${cls.map(x=>`<option${c==x?' selected':''}>${esc(x)}</option>`).join('')}</select></label><div class="mu" style="margin:0 0 4px">Students (tick the names)</div><div id="hwl" style="max-height:190px;overflow:auto;border:1px solid #d5d9e4;border-radius:10px;padding:8px 10px;margin-bottom:12px"></div><label>Subject<input id="hws" list="hwsl" autocomplete="off" value="${esc(h?h.subject:me)}" placeholder="e.g. Mathematics"><datalist id="hwsl">${rcSubs().map(x=>`<option value="${esc(x)}">`).join('')}</datalist></label><label>Title<input id="hwti" autocomplete="off" value="${esc(h?h.title:'')}" placeholder="e.g. Exercise 4.2 questions 1 to 10"></label><label>Details<textarea id="hwd" rows="3" placeholder="What the student has to do">${esc(h?h.desc:'')}</textarea></label><label>Due date<input id="hwdu" type="date" value="${esc(h?h.due:'')}"></label><div class="ra"><button type="button" class="bt gh" data-a="close">Cancel</button><button type="button" class="bt" data-hw="save">Save</button></div></form>`;hwFill(h?h.sids:[]);$('#hwf').onsubmit=e=>{e.preventDefault();hwSave()}}
function hwSave(){const f=$('#hwf'),id=f.dataset.id,sids=[...document.querySelectorAll('.hwk:checked')].map(x=>+x.value),t=$('#hwti').value.trim(),sb=$('#hws').value.trim();if(!sids.length){toast('Tick at least one student');return}if(!sb){toast('Write the subject');return}if(sids.some(k=>{const x=S.students.find(z=>z.id==k);return x&&!TSUBOK(x,sb)})){toast('You can give homework only in your subject of that class: '+(TSUBSFOR($('#hwc').value).join(', ')||'no subject set'));return}if(!t){toast('Write the homework title');return}
const me=hwMe(),o={type:$('#hwt').value,cls:$('#hwc').value,sids,subject:sb,title:t,desc:$('#hwd').value.trim(),due:$('#hwdu').value};S.hw=S.hw||[];
if(id){const h=S.hw.find(x=>x.id==id);if(!h)return;Object.assign(h,o)}else{S.hw.push(Object.assign({id:uid(),by:me.name,byId:me.id,on:hwToday()},o));sids.forEach(k=>{const s=S.students.find(x=>x.id==k);if(s)sendMsg(s.id,'Homework notice','Dear '+s.guardian+', new '+o.type.toLowerCase()+' for '+s.name+' in '+sb+': '+t+(o.due?'. Due '+hwDue(o):'')+'. Details are in the Parent Portal.')})}
lg(o.type+' saved: '+o.cls+' '+sb);try{save()}catch(e){}$('#md').hidden=true;toast(o.type+' saved for '+sids.length+' student'+(sids.length>1?'s':''));draw()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-hw]');if(!b)return;const a=b.dataset.hw;if(a=='add')hwModal();else if(a=='edit')hwModal(b.dataset.id);else if(a=='save')hwSave();else if(a=='del'){if(!b.dataset.armed){b.dataset.armed=1;b.textContent='Tap again to delete';return}S.hw=(S.hw||[]).filter(h=>h.id!=b.dataset.id);try{save()}catch(x){}toast('Deleted');draw()}});
document.addEventListener('change',e=>{const x=e.target;if(!x)return;if(x.dataset&&x.dataset.hwf){FL.hwc=x.value;draw()}else if(x.id=='hwc')hwFill([]);else if(x.id=='hwall')document.querySelectorAll('.hwk').forEach(i=>i.checked=x.checked)});

/* ===== Report card approval: teacher sends, admin approves, then it shows in Student/Parent portal ===== */
function rcApKey(c,t){return c+'|'+t}
function rcAp(c,t){S.rcap=S.rcap||{};return S.rcap[rcApKey(c,t)]||{st:'Draft'}}
function rcPub(s){return S.exams.filter(e=>e.sid==s.id&&rcAp(rcLbl(s),e.test).st=='Approved')}
function rcIsAdm(){const u=SES();return u.role=='admin'||(u.role=='employee'&&(S.staff.find(x=>x.id==u.id)||{}).role=='Principal')}
function rcApBar(c,st){const a=st.st,adm=rcIsAdm();let t,b='',ct=rcCT(c.cls).map(x=>x.name).join(', ')||'not assigned';
if(a=='Approved'){t='Published to the Student and Parent portal'+(st.appBy?' (approved by '+esc(st.appBy)+' on '+esc(st.appOn||'')+')':'')+'.';if(adm)b='<button class="bt gh" data-rc="ap-reopen">Unpublish / reopen</button>'}
else if(a=='Pending'){t='Sent for approval by '+esc(st.by||'teacher')+' on '+esc(st.on||'')+'. Students and parents cannot see it yet.';if(adm)b='<button class="bt" data-rc="ap-ok">Approve &amp; publish</button><button class="bt gh" data-rc="ap-no">Send back</button>'}
else{t=(a=='Rejected'?'Sent back by admin'+(st.note?': '+esc(st.note):'')+'. Fix the marks and send again. ':'')+'Not published. Students and parents cannot see this report card yet.';if(rcCanSend(c.cls))b='<button class="bt" data-rc="ap-send">'+ic('send')+'Send class to admin for approval</button>';else t+=' Only the class teacher ('+esc(ct)+') can send it to admin.'}
return`<div class="card rap" style="margin-bottom:14px"><div class="rap-h"><div class="rap-t"><b>${esc(c.cls)}</b><small>${esc(c.test)}</small></div>${badge(a=='Draft'?'Not sent':a)}</div><div class="rap-i"><span>Class teacher</span><b>${esc(ct)}</b></div><p class="rap-n">${t}</p>${b?`<div class="rap-b">${b}</div>`:''}</div>`}
function rcPendList(){if(!rcIsAdm())return'';const L=Object.entries(S.rcap||{}).filter(([k,v])=>v.st=='Pending');if(!L.length)return'';return`<div class="card" style="margin-bottom:14px"><h3>Waiting for approval (${L.length})</h3>${L.map(([k,v])=>{const p=k.split('|');return`<div class="cb"><span>${esc(p[0])} - ${esc(p[1])} <span class="mu">sent by ${esc(v.by||'')}</span></span><button class="bt gh sm" style="margin-left:auto" data-rc="ap-open" data-k="${esc(k)}">Open</button></div>`}).join('')}</div>`}
document.addEventListener('click',e=>{const b=e.target.closest('[data-rc]');if(!b)return;const a=b.dataset.rc;if(a.slice(0,3)!='ap-')return;const c=rcCfg();S.rcap=S.rcap||{};const k=rcApKey(c.cls,c.test),done=m=>{try{save()}catch(x){}toast(m);draw()};
if(a=='ap-open'){const p=b.dataset.k.split('|');c.cls=p[0];c.test=p[1];draw();rcReview(b.dataset.k);return}
if(a=='ap-send'){if(!rcCanSend(c.cls)){toast('Only the class teacher of '+c.cls+' can send this report card to admin');return}if(!S.students.some(s=>rcLbl(s)==c.cls&&s.status=='Active'&&rcBuild(s,c.test).rows.length)){toast('Enter some marks first');return}S.rcap[k]={st:'Pending',by:hwMe().name,on:hwToday()};lg('Report card sent for approval: '+k);done('Sent to admin for approval');return}
if(!rcIsAdm())return;
if(a=='ap-ok'){const me=hwMe();S.rcap[k]={st:'Approved',by:(S.rcap[k]||{}).by,on:(S.rcap[k]||{}).on,appBy:me.name,appOn:hwToday()};S.students.filter(s=>rcLbl(s)==c.cls&&s.status=='Active'&&rcBuild(s,c.test).rows.length).forEach(s=>sendMsg(s.id,'Result notification','Dear '+s.guardian+', the '+c.test+' report card of '+s.name+(s.roll?' (Roll no '+s.roll+')':'')+' is ready in the Parent Portal.'));lg('Report card approved: '+k);done('Approved. Report card is now visible to students and parents of '+c.cls);return}
if(a=='ap-no'){const m=$('#md');m.hidden=false;m.innerHTML='<form class="mb" onsubmit="return false"><h3>Send back to teacher</h3><label>Reason (optional)<textarea id="rcnote" rows="3" placeholder="What should the teacher correct?"></textarea></label><div class="ra"><button type="button" class="bt gh" data-a="close">Cancel</button><button type="button" class="bt" data-rc="ap-nosave">Send back</button></div></form>';return}
if(a=='ap-nosave'){const o=S.rcap[k]||{};S.rcap[k]={st:'Rejected',by:o.by,on:o.on,note:($('#rcnote').value||'').trim()};$('#md').hidden=true;lg('Report card sent back: '+k);done('Sent back to the teacher');return}
if(a=='ap-reopen'){S.rcap[k]={st:'Draft'};lg('Report card unpublished: '+k);done('Unpublished. Students and parents can no longer see it');return}});

/* ===== Approvals menu: admin approves report cards sent by teachers ===== */
function apvRows(){S.rcap=S.rcap||{};return Object.entries(S.rcap).map(([k,v])=>{const p=k.split('|');return Object.assign({k,cls:p[0],test:p[1]},v)})}
function apvStat(r){const kids=S.students.filter(s=>rcLbl(s)==r.cls&&s.status=='Active'),b=kids.map(s=>rcBuild(s,r.test)).filter(x=>x.rows.length),sb=new Set();b.forEach(x=>x.rows.forEach(e=>sb.add(e.subject)));return{n:b.length,all:kids.length,avg:b.length?Math.round(b.reduce((a,x)=>a+x.pc,0)/b.length):0,subs:[...sb]}}
function apvRes(cls,test){const kids=S.students.filter(s=>rcLbl(s)==cls&&s.status=='Active'),L=kids.map(s=>Object.assign({s},rcBuild(s,test))).filter(x=>x.rows.length).sort((a,b)=>b.pc-a.pc),ps=L.filter(x=>x.gd!='F');let pos=0,last=-1;L.forEach((x,i)=>{if(x.pc!=last){pos=i+1;last=x.pc}x.pos=pos});return{L,pass:ps.length,fail:L.length-ps.length,top:L[0]}}
function apvResult(k){const p=String(k).split('|'),R=apvRes(p[0],p[1]),st=(S.rcap||{})[k]||{st:'Draft'},m=$('#md');m.hidden=false;m.innerHTML=`<div class="mb rp-mb"><div class="rp-mh"><div><h3>${esc(p[0])} &middot; ${esc(p[1])} - Results</h3><p class="mu" style="margin:2px 0 0">Position-wise result of the class</p></div>${badge(st.st=='Draft'?'Not sent':st.st)}</div><div class="rp-kp"><div><b>${R.L.length}</b><small>Students</small></div><div><b style="color:#15803d">${R.pass}</b><small>Passed</small></div><div><b style="color:#be123c">${R.fail}</b><small>Failed</small></div></div>${R.top?`<p class="mu" style="margin:8px 0">Topper: <b>${esc(R.top.s.name)}</b> (${R.top.pc}%)</p>`:''}<div class="ar-list">${R.L.map(x=>`<div class="ar-r"><span class="ar-p">${x.pos}</span><div class="ar-n"><b>${esc(x.s.name)}</b><small>${x.s.roll?'Roll '+esc(x.s.roll)+' &middot; ':''}${x.g}/${x.t}</small></div><div class="ar-s"><b>${x.pc}%</b><span>${badge(x.gd)} ${x.gd=='F'?badge('Failed'):badge('Passed')}</span></div></div>`).join('')||'<p class="em">No marks entered yet.</p>'}</div><div class="ra rp-ra"><button type="button" class="bt gh" data-a="close">Close</button></div></div>`}
function apvCard(r){const t=apvStat(r),k=esc(r.k),R=apvRes(r.cls,r.test);return`<div class="card" style="margin-bottom:12px"><div class="cb"><b>${esc(r.cls)} - ${esc(r.test)}</b>&nbsp;${badge(r.st)}<span class="mu" style="margin:0 0 0 auto">${t.n} of ${t.all} students &middot; class average ${t.avg}%</span></div><p class="mu">Class teacher: ${esc(rcCT(r.cls).map(x=>x.name).join(', ')||'not assigned')}<br>Subjects: ${esc(t.subs.join(', ')||'none')}<br>${r.st=='Approved'?'Approved by '+esc(r.appBy||'')+' on '+esc(r.appOn||''):'Sent by '+esc(r.by||'')+' on '+esc(r.on||'')}${r.note?'<br>Reason: '+esc(r.note):''}</p><div class="apr"><div><b>${R.pass}</b><small>Passed</small></div><div><b>${R.fail}</b><small>Failed</small></div><div><b>${R.top?R.top.pc+'%':'-'}</b><small>${R.top?esc(R.top.s.name):'Topper'}</small></div></div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="bt sm" data-ap="result" data-k="${k}">View results</button><button class="bt gh sm" data-ap="view" data-k="${k}">View marks</button>${r.st=='Pending'?`<button class="bt sm" data-ap="ok" data-k="${k}">Approve &amp; publish</button><button class="bt gh sm" data-ap="no" data-k="${k}">Send back</button>`:''}${r.st=='Approved'?`<button class="bt gh sm" data-ap="reopen" data-k="${k}">Unpublish</button>`:''}</div></div>`}
function apvPage(){const R=apvRows().filter(r=>r.st!='Draft'),g=x=>R.filter(r=>r.st==x),sec=(t,L)=>L.length?`<h3 style="margin:16px 2px 10px">${t} (${L.length})</h3>`+L.map(apvCard).join(''):'';
return`<div class="g4">${stat('tim','Waiting for approval',g('Pending').length,'Report cards from teachers','c-b')}${stat('chk','Published',g('Approved').length,'Visible to students and parents','c-g')}${stat('del','Sent back',g('Rejected').length,'Teacher must correct','c-r')}</div>`+apvCTCard()+(R.length?sec('Waiting for approval',g('Pending'))+sec('Sent back to teacher',g('Rejected'))+sec('Published',g('Approved')):'<div class="card em" style="margin-top:14px">No report cards have been sent for approval yet. Teachers send them from the Examinations page.</div>')+apvTeacherSec()}
function apvView(k){const p=k.split('|'),kids=S.students.filter(s=>rcLbl(s)==p[0]&&s.status=='Active').sort((a,b)=>(parseInt(a.roll)||9999)-(parseInt(b.roll)||9999)||String(a.name).localeCompare(b.name)),subs=rcSubs().filter(sb=>kids.some(s=>rcFind(s.id,sb,p[1]))),m=$('#md');m.hidden=false;
m.innerHTML=`<div class="mb"><h3>${esc(p[0])} - ${esc(p[1])}: marks</h3><div class="tw cv"><table><thead><tr><th>Roll</th><th>Student</th>${subs.map(x=>`<th>${esc(x)}</th>`).join('')}<th>Total</th><th>%</th><th>Grade</th></tr></thead><tbody>${kids.map(s=>{const r=rcBuild(s,p[1]);return`<tr><td>${esc(s.roll||'')}</td><td class="ttl">${esc(s.name)}</td>${subs.map(x=>{const e=rcFind(s.id,x,p[1]);return`<td>${e?e.marks+'/'+e.total:'-'}</td>`}).join('')}<td>${r.rows.length?r.g+'/'+r.t:'-'}</td><td>${r.rows.length?r.pc+'%':'-'}</td><td>${r.rows.length?badge(r.gd):''}</td></tr>`}).join('')||'<tr><td class="em">No students.</td></tr>'}</tbody></table></div><div class="ra"><button type="button" class="bt gh" data-a="close">Close</button></div></div>`}
document.addEventListener('click',e=>{const b=e.target.closest('[data-ap]');if(!b)return;const a=b.dataset.ap,k=b.dataset.k;if(a=='view'){rcReview(k);return}if(a=='result'){apvResult(k);return}if(a=='tview'){apvTView(k,b.dataset.t);return}if(!rcIsAdm())return;S.rcap=S.rcap||{};const o=S.rcap[k]||{},p=(k||'').split('|'),done=m=>{try{save()}catch(x){}toast(m);draw()};
if(a=='ok'){S.rcap[k]={st:'Approved',by:o.by,on:o.on,appBy:hwMe().name,appOn:hwToday()};S.students.filter(s=>rcLbl(s)==p[0]&&s.status=='Active'&&rcBuild(s,p[1]).rows.length).forEach(s=>sendMsg(s.id,'Result notification','Dear '+s.guardian+', the '+p[1]+' report card of '+s.name+(s.roll?' (Roll no '+s.roll+')':'')+' is ready in the Parent Portal.'));lg('Report card approved: '+k);done('Approved. '+p[0]+' students and parents can now see it');return}
if(a=='no'){const m=$('#md');m.hidden=false;m.innerHTML=`<form class="mb" onsubmit="return false"><h3>Send back to teacher</h3><label>Reason (optional)<textarea id="apnote" rows="3" placeholder="What should the teacher correct?"></textarea></label><div class="ra"><button type="button" class="bt gh" data-a="close">Cancel</button><button type="button" class="bt" data-ap="nosave" data-k="${esc(k)}">Send back</button></div></form>`;return}
if(a=='nosave'){S.rcap[k]={st:'Rejected',by:o.by,on:o.on,note:($('#apnote').value||'').trim()};$('#md').hidden=true;lg('Report card sent back: '+k);done('Sent back to the teacher');return}
if(a=='reopen'){S.rcap[k]={st:'Draft'};lg('Report card unpublished: '+k);done('Unpublished. Students and parents can no longer see it')}});

/* ===== Approvals: marks shown teacher by teacher ===== */
function apvTeach(e){return e.by||((S.staff.find(t=>t.role=='Teacher'&&String(t.subject||'').split(/[,&]/).some(v=>v.trim().toLowerCase()==String(e.subject||'').trim().toLowerCase()))||{}).name)||'Not assigned'}
function apvTG(){const T={};S.exams.forEach(e=>{const s=S.students.find(x=>x.id==e.sid);if(!s)return;const t=apvTeach(e),k=rcLbl(s)+'|'+e.test+'|'+String(e.subject||'').trim();((T[t]=T[t]||{})[k]=T[t][k]||[]).push(e)});return T}
function apvTeacherSec(){const T=apvTG(),names=Object.keys(T).sort();if(!names.length)return'';return`<h3 style="margin:18px 2px 10px">Teacher-wise marks (${names.length})</h3>`+names.map(n=>{const rows=Object.keys(T[n]).sort().map(k=>{const p=k.split('|'),L=T[n][k],all=S.students.filter(s=>rcLbl(s)==p[0]&&s.status=='Active').length,avg=Math.round(L.reduce((a,e)=>a+e.marks/e.total*100,0)/L.length),st=rcAp(p[0],p[1]).st;return`<tr><td>${esc(p[0])}</td><td>${esc(p[1])}</td><td>${esc(p[2])}</td><td>${L.length} of ${all}</td><td>${avg}%</td><td>${badge(st=='Draft'?'Not sent':st)}</td><td><button class="bt gh sm" data-ap="tview" data-k="${esc(k)}" data-t="${esc(n)}">View</button></td></tr>`}).join('');return`<div class="card" style="margin-bottom:12px"><h3>${esc(n)}</h3><div class="tw cv"><table><thead><tr><th>Class</th><th>Test</th><th>Subject</th><th>Marks entered</th><th>Average</th><th>Status</th><th></th></tr></thead><tbody>${rows}</tbody></table></div></div>`}).join('')}
function apvTView(k,t){const p=k.split('|'),kids=S.students.filter(s=>rcLbl(s)==p[0]&&s.status=='Active').sort((a,b)=>(parseInt(a.roll)||9999)-(parseInt(b.roll)||9999)||String(a.name).localeCompare(b.name)),m=$('#md');m.hidden=false;
m.innerHTML=`<div class="mb"><h3>${esc(t)}</h3><p class="mu">${esc(p[2])} &middot; ${esc(p[0])} &middot; ${esc(p[1])}</p><div class="tw cv"><table><thead><tr><th>Roll</th><th>Student</th><th>Marks</th><th>%</th><th>Grade</th></tr></thead><tbody>${kids.map(s=>{const e=rcFind(s.id,p[2],p[1]),ok=e&&apvTeach(e)==t;return`<tr><td>${esc(s.roll||'')}</td><td class="ttl">${esc(s.name)}</td>${ok?`<td>${e.marks} / ${e.total}</td><td>${Math.round(e.marks/e.total*100)}%</td><td>${badge(gr(e.marks/e.total*100))}</td>`:'<td>-</td><td>-</td><td></td>'}</tr>`}).join('')||'<tr><td class="em">No students.</td></tr>'}</tbody></table></div><div class="ra"><button type="button" class="bt gh" data-a="close">Close</button></div></div>`}

/* ===== Class teacher sends the whole class report card to admin ===== */
function rcCT(cls){return S.staff.filter(t=>t.role=='Teacher'&&t.status!='Resigned'&&rcStaffLbl(t)==cls)}
function rcCanSend(cls){const u=SES();if(rcIsAdm())return true;if(u.role!='employee')return false;const L=rcCT(cls);return!L.length||L.some(t=>t.id==u.id)}

function rcStaffLbl(t){return t.cls&&t.cls!='None'?t.cls+(t.csec?' - '+String(t.csec).trim().toUpperCase():''):''}
function rcLabels(){const set=new Set();S.students.forEach(s=>set.add(rcLbl(s)));CL.forEach(c=>{if(!S.students.some(s=>s.cls==c))set.add(c)});S.staff.forEach(t=>{const l=rcStaffLbl(t);if(l)set.add(l)});return[...set].sort((x,y)=>{const i=CL.indexOf(x.split(' - ')[0]),j=CL.indexOf(y.split(' - ')[0]);return(i<0?99:i)-(j<0?99:j)||x.localeCompare(y)})}

function rcLbl(s){return S.staff.some(t=>t.role=='Teacher'&&t.status!='Resigned'&&rcStaffLbl(t)==s.cls)?s.cls:scl(s)}

/* ===== Approvals: which teacher is class teacher of which class/section, and report card status ===== */
function apvCTCard(){const L=rcLabels();return`<div class="card" style="margin:14px 0"><h3>Class teachers</h3><p class="mu">Each class teacher makes the complete report card of her class and sends it to admin. Set a teacher's class in Teachers &amp; Staff (Class teacher of).</p><div class="tw cv"><table><thead><tr><th>Class</th><th>Class teacher</th><th>Students</th>${['Monthly test','Midterm','Final'].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${L.map(l=>{const ct=rcCT(l).map(t=>t.name).join(', ');return`<tr><td class="ttl">${esc(l)}</td><td>${ct?esc(ct):'<span class="mu">Not assigned</span>'}</td><td>${S.students.filter(s=>scl(s)==l&&s.status=='Active').length}</td>${['Monthly test','Midterm','Final'].map(t=>{const st=rcAp(l,t).st;return`<td>${badge(st=='Draft'?'Not sent':st)}</td>`}).join('')}</tr>`}).join('')}</tbody></table></div></div>`}

/* ===== mobile: turn every table into labelled cards + one-screen dashboard flag ===== */
(function(){
var TT=/^(name|student|teacher|staff|employee|title|category|class|subject|item|description)$/i;
function fix(){
try{
document.body.classList.toggle('on-dash',!!document.querySelector('#v>.dsh'));
document.querySelectorAll('.app table:not(.fm-t)').forEach(function(t){
var hs=[].map.call(t.querySelectorAll('thead th'),function(h){return h.textContent.trim()});
if(!hs.length)return;
t.classList.add('rt');
var ti=-1;hs.forEach(function(h,i){if(ti<0&&TT.test(h))ti=i});if(ti<0)ti=0;
t.querySelectorAll('tbody>tr').forEach(function(tr){
var c=[].slice.call(tr.children);
if(c.length==1||(c[0]&&c[0].hasAttribute('colspan'))){tr.classList.add('emr');return}
var hasT=tr.querySelector('td.ttl');
c.forEach(function(td,i){
var l=hs[i]||'';
if(l&&!td.dataset.l)td.dataset.l=l;
if(!l&&i==c.length-1)td.classList.add('ac');
if(/^status$/i.test(l))td.classList.add('stt');
if(!hasT&&i==ti&&!td.classList.contains('stt')&&!td.classList.contains('ac'))td.classList.add('ttl');
if(td.querySelector('input,select,textarea')&&!td.classList.contains('ttl'))td.classList.add('wd');
});
});
});
}catch(e){}
}
var q=0;function sch(){if(q)return;q=requestAnimationFrame(function(){q=0;fix()})}
function init(){new MutationObserver(sch).observe(document.body,{childList:true,subtree:true});window.addEventListener('hashchange',sch);fix()}
if(document.readyState=='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();

