  var hr=table.tHead&&table.tHead.rows.length?table.tHead.rows[table.tHead.rows.length-1]:table.rows[0];
  if(!hr)return null;
  var head=rowCells(hr),keep=[];
  head.forEach(function(h,i){if(h!=='')keep.push(i)});
