    if(tr.children.length===1&&/(^|\s)em(\s|$)/.test(tr.children[0].className||''))return;
    if(tr.children.length===1&&/^(nothing here|no data|no records|no .* yet|nothing to show)/i.test(cells[0]||''))return;
