'<span class="cfi" data-s="year"><select data-k="y">'+[...yrs].sort((x,y)=>y-x).map(y=>'<option>'+y+'</option>').join('')+'</select></span>'+
'<span class="cfi" data-s="range"><input type="date" data-k="f"> to <input type="date" data-k="t"></span><button type="button" data-k="x">Reset</button><span class="cfn"></span>';
const sync=()=>{bar.querySelectorAll('[data-k]').forEach(e=>{const k=e.dataset.k;if(k!='x'&&st[k]!=null)e.value=st[k]});if(!st.y)st.y=bar.querySelector('[data-k=y]').value;bar.querySelectorAll('[data-s]').forEach(e=>e.style.display=e.dataset.s==st.m?'inline-flex':'none')};
